// Actor item grant/editing, abilities, currency, HP — extracted from mobile-bridge.js.

export function isEmptyConsumableAmmoStub(doc) {
  if (!doc || doc.type !== "consumable") return false;
  if (String(doc.system?.type?.value ?? "") !== "ammo") return false;
  const base = doc.system?.damage?.base;
  if (!base || typeof base !== "object") return true;
  const hasDice = Number(base.number) > 0 && Number(base.denomination) > 0;
  const hasCustom = !!(base.custom?.enabled && String(base.custom?.formula ?? "").trim());
  return !hasDice && !hasCustom;
}

/**
 * Exact-name weapon lookup across Item packs. Prefers non-world packs
 * (system/module) over world.ddb-* stubs.
 */
export async function findExactNameWeaponDocument(name, excludeUuid = "") {
  const wanted = normalizeOfflineName(name);
  if (!wanted) return null;
  const hits = [];
  for (const pack of game.packs) {
    if (packDocumentName(pack) !== "Item") continue;
    let index;
    try {
      index = pack.index ?? await pack.getIndex({ fields: ["name", "type", "img"] });
    } catch {
      continue;
    }
    for (const entry of iterateCompendiumIndex(index)) {
      if (String(entry?.type ?? "") !== "weapon") continue;
      if (normalizeOfflineName(entry?.name) !== wanted) continue;
      const entryUuid = resolveCompendiumEntryUuid(pack, entry);
      if (!entryUuid || entryUuid === excludeUuid) continue;
      hits.push({
        uuid: entryUuid,
        pack: pack.collection,
        worldPack: String(pack.collection ?? "").startsWith("world.")
      });
    }
  }
  if (!hits.length) return null;
  hits.sort((a, b) => Number(a.worldPack) - Number(b.worldPack));
  grantLog("resolve.weaponAlternate.candidates", {
    wanted,
    count: hits.length,
    hits: hits.slice(0, 8)
  });
  const doc = await fromUuid(hits[0].uuid);
  return doc?.documentName === "Item" && doc.type === "weapon" ? doc : null;
}

/**
 * Resolve an Item document from a Foundry UUID, with exact-name pack fallback
 * when the UUID is stale (content-server index vs packs on this world).
 * Also replaces empty DDB consumable/ammo "weapons" with a real weapon match.
 */
export async function resolveItemDocumentForGrant(uuid, nameHint = "") {
  const rawUuid = String(uuid ?? "").trim();
  grantLog("resolve.start", { uuid: rawUuid, nameHint: nameHint || null, pipeline: GRANT_PIPELINE });
  let doc = null;
  if (rawUuid) {
    try {
      doc = await fromUuid(rawUuid);
    } catch (err) {
      grantWarn("resolve.fromUuid threw", { uuid: rawUuid, err: String(err?.message ?? err) });
    }
    grantLog("resolve.fromUuid", {
      uuid: rawUuid,
      found: !!doc,
      documentName: doc?.documentName ?? null,
      summary: summarizeGrantItem(doc, "fromUuid")
    });
    if (doc && doc.documentName !== "Item") {
      grantWarn("resolve.fromUuid wrong documentName", {
        uuid: rawUuid,
        documentName: doc.documentName
      });
      doc = null;
    }
  }

  if (doc?.documentName === "Item" && isEmptyConsumableAmmoStub(doc)) {
    const alt = await findExactNameWeaponDocument(doc.name || nameHint, doc.uuid);
    if (alt) {
      grantWarn("resolve.replacedEmptyAmmoStubWithWeapon", {
        from: summarizeGrantItem(doc, "stub"),
        to: summarizeGrantItem(alt, "weapon")
      });
      return alt;
    }
    grantWarn("resolve.emptyAmmoStubNoWeaponAlternate", summarizeGrantItem(doc, "stub"));
  }

  if (doc?.documentName === "Item") return doc;

  const wanted = normalizeOfflineName(nameHint);
  if (!wanted) {
    grantWarn("resolve.failed", { uuid: rawUuid, reason: "no doc and no nameHint" });
    return null;
  }
  // Prefer already-loaded pack indexes first so offline submitBatch does not
  // await getIndex on every pack (that routinely exceeds the mobile timeout).
  const hits = [];
  const deferredPacks = [];
  for (const pack of game.packs) {
    if (packDocumentName(pack) !== "Item") continue;
    if (pack.index) {
      for (const entry of iterateCompendiumIndex(pack.index)) {
        if (normalizeOfflineName(entry?.name) !== wanted) continue;
        const entryUuid = resolveCompendiumEntryUuid(pack, entry);
        if (!entryUuid) continue;
        hits.push({
          uuid: entryUuid,
          pack: pack.collection,
          type: entry?.type ?? null,
          name: entry?.name ?? null,
          worldPack: String(pack.collection ?? "").startsWith("world.")
        });
      }
    } else {
      deferredPacks.push(pack);
    }
  }
  if (!hits.length) {
    for (const pack of deferredPacks) {
      let index;
      try {
        index = await pack.getIndex({ fields: ["name", "type", "img"] });
      } catch (err) {
        grantWarn("resolve.indexFailed", { pack: pack.collection, err: String(err?.message ?? err) });
        continue;
      }
      for (const entry of iterateCompendiumIndex(index)) {
        if (normalizeOfflineName(entry?.name) !== wanted) continue;
        const entryUuid = resolveCompendiumEntryUuid(pack, entry);
        if (!entryUuid) continue;
        hits.push({
          uuid: entryUuid,
          pack: pack.collection,
          type: entry?.type ?? null,
          name: entry?.name ?? null,
          worldPack: String(pack.collection ?? "").startsWith("world.")
        });
      }
      if (hits.length) break;
    }
  }
  grantLog("resolve.nameFallback", {
    wanted,
    hitCount: hits.length,
    hits: hits.slice(0, 10)
  });
  if (!hits.length) {
    grantWarn("resolve.failed", { uuid: rawUuid, reason: "nameFallback zero hits" });
    return null;
  }
  hits.sort((a, b) => {
    const rank = (t) => (t === "weapon" ? 0 : t === "equipment" ? 1 : 2);
    const r = rank(a.type) - rank(b.type);
    if (r !== 0) return r;
    return Number(a.worldPack) - Number(b.worldPack);
  });
  const chosen = await fromUuid(hits[0].uuid);
  grantLog("resolve.nameFallback.doc", {
    chosen: summarizeGrantItem(chosen, "nameFallback"),
    pickedFrom: hits[0]
  });
  return chosen?.documentName === "Item" ? chosen : null;
}

/**
 * Add an Item to the actor by UUID. Uses the same drop path as dragging from a
 * compendium onto the sheet (fromDropData → fromCompendium) so activities and
 * damage survive. Bare toObject() historically produced empty consumable stubs.
 */
export async function actorItemCreate(user, actorId, uuid, nameHint = "") {
  const actor = getOwnedActor(user, actorId);
  grantLog("create.start", {
    user: user?.name,
    userId: user?.id,
    role: user?.role,
    actorId,
    actorName: actor?.name,
    uuid,
    nameHint: nameHint || null,
    pipeline: GRANT_PIPELINE
  });
  if (!uuid || typeof uuid !== "string") {
    throw new Error("uuid is required");
  }
  const doc = await resolveItemDocumentForGrant(uuid, nameHint);
  if (!doc) throw new Error(`Document not found: ${uuid}`);
  const sourceType = doc.type;
  grantLog("create.source", summarizeGrantItem(doc, "source"));

  const ItemCls = CONFIG.Item?.documentClass ?? Item;
  let dataList = null;
  let method = null;

  // 1) Official drag-drop import (preferred).
  if (typeof ItemCls.fromDropData === "function") {
    try {
      const dropped = await ItemCls.fromDropData({ type: "Item", uuid: doc.uuid });
      grantLog("create.fromDropData.raw", {
        isItem: dropped instanceof Item,
        summary: summarizeGrantItem(dropped, "fromDropData")
      });
      if (dropped instanceof Item) {
        dataList = typeof game.items?.fromCompendium === "function"
          ? [game.items.fromCompendium(dropped)]
          : [(() => { const o = dropped.toObject(); delete o._id; return o; })()];
        method = typeof game.items?.fromCompendium === "function"
          ? "fromDropData+fromCompendium"
          : "fromDropData+toObject";
      } else if (dropped && typeof dropped === "object") {
        const o = foundry.utils.deepClone(dropped);
        delete o._id;
        dataList = [o];
        method = "fromDropData-object";
      }
    } catch (err) {
      grantWarn("create.fromDropData failed, trying createWithContents", String(err?.message ?? err), err);
    }
  } else {
    grantLog("create.fromDropData unavailable");
  }

  // 2) dnd5e container-aware copy.
  if (!dataList?.length && typeof ItemCls.createWithContents === "function") {
    try {
      dataList = await ItemCls.createWithContents([doc], { keepId: false });
      method = "createWithContents";
      grantLog("create.createWithContents", {
        count: dataList?.length ?? 0,
        first: summarizeGrantItem(dataList?.[0], "createWithContents[0]")
      });
    } catch (err) {
      grantWarn("create.createWithContents failed, trying fromCompendium", String(err?.message ?? err), err);
    }
  }

  // 3) Pack transform only.
  if (!dataList?.length && typeof game.items?.fromCompendium === "function") {
    dataList = [game.items.fromCompendium(doc)];
    method = "fromCompendium";
    grantLog("create.fromCompendium", summarizeGrantItem(dataList[0], "fromCompendium"));
  }

  // 4) Last resort.
  if (!dataList?.length) {
    const data = doc.toObject();
    delete data._id;
    dataList = [data];
    method = "toObject-fallback";
    grantWarn("create.using bare toObject fallback", summarizeGrantItem(dataList[0], "toObject"));
  }

  grantLog("create.prepared", {
    method,
    count: dataList.length,
    items: dataList.map((d, i) => summarizeGrantItem(d, `prepared[${i}]`))
  });

  const created = await actor.createEmbeddedDocuments("Item", dataList, { keepId: true });
  const first = created?.[0];
  if (!first) throw new Error(`Failed to create item from: ${uuid}`);

  grantLog("create.embedded", {
    method,
    createdCount: created.length,
    owned: summarizeGrantItem(first, "owned"),
    sourceType,
    createdType: first.type
  });

  // Refuse silent corruption into an empty ammo/consumable stub.
  if (sourceType && first.type !== sourceType) {
    grantError(
      `grant type mismatch for "${first.name}": source=${sourceType} created=${first.type}; deleting stub`,
      { source: summarizeGrantItem(doc, "source"), created: summarizeGrantItem(first, "created") }
    );
    await first.delete();
    throw new Error(
      `Grant produced ${first.type} instead of ${sourceType} for ${uuid}. Check the compendium UUID.`
    );
  }

  grantLog("create.ok", {
    pipeline: GRANT_PIPELINE,
    method,
    name: first.name,
    type: first.type,
    id: first.id,
    uuid: first.uuid
  });
  return {
    accepted: true,
    itemId: first.id,
    name: first.name,
    itemType: first.type
  };
}

/**
 * Remove an owned Item from the actor.
 */
export async function actorItemDelete(user, actorId, itemId) {
  const actor = getOwnedActor(user, actorId);
  if (!itemId || typeof itemId !== "string") {
    throw new Error("itemId is required");
  }
  const item = actor.items.get(itemId);
  if (!item) throw new Error(`Item not found on actor: ${itemId}`);

  const Manager = getAdvancementManagerClass();
  const manager = Manager.forDeletedItem(actor, itemId);
  if (!manager.steps.length) {
    await actor.deleteEmbeddedDocuments("Item", [itemId]);
    return { accepted: true, advancementReversed: false };
  }

  const session = {
    sessionId: foundry.utils.randomID(),
    userId: user.id,
    actorId,
    manager,
    stepIndex: 0,
    createdAt: Date.now()
  };
  await advanceAutomaticSteps(session);
  if (session.stepIndex < manager.steps.length) {
    throw new Error(`Item deletion advancement stopped on a non-automatic step: ${manager.steps[session.stepIndex]?.type}`);
  }
  await commitAdvancementManager(manager);
  return { accepted: true, advancementReversed: true };
}

/**
 * Set the absolute quantity of an owned inventory item. quantity <= 0 deletes
 * the item entirely (so the mobile UI can drive a `-` button down to removal
 * without needing a separate delete call).
 */
export async function actorItemSetQuantity(user, actorId, itemId, quantity) {
  const actor = getOwnedActor(user, actorId);
  if (!itemId || typeof itemId !== "string") {
    throw new Error("itemId is required");
  }
  const qty = Number(quantity);
  if (!Number.isFinite(qty)) throw new Error("quantity must be a number");
  const floored = Math.max(0, Math.floor(qty));
  const item = actor.items.get(itemId);
  if (!item) throw new Error(`Item not found on actor: ${itemId}`);
  if (floored <= 0) {
    const result = await actorItemDelete(user, actorId, itemId);
    return { ...result, deleted: true, quantity: 0 };
  }
  const capped = item.type === "spell"
    ? floored
    : Math.min(ITEM_QUANTITY_MAX, floored);
  await item.update({ "system.quantity": capped });
  return { accepted: true, deleted: false, quantity: capped };
}

/**
 * Toggle or set equipped state (dnd5e: system.equipped on weapons/equipment/etc.).
 */
export async function actorItemSetEquipped(user, actorId, itemId, equipped) {
  const actor = getOwnedActor(user, actorId);
  if (!itemId || typeof itemId !== "string") {
    throw new Error("itemId is required");
  }
  const item = actor.items.get(itemId);
  if (!item) throw new Error(`Item not found on actor: ${itemId}`);
  if (!("equipped" in (item.system ?? {}))) {
    throw new Error("Item cannot be equipped");
  }
  const next = equipped === undefined || equipped === null
    ? !item.system.equipped
    : Boolean(equipped);
  await item.update({ "system.equipped": next });
  return { accepted: true, equipped: next };
}

/**
 * Attune / un-attune a magic item (dnd5e: system.attuned). Only items that
 * require attunement can be toggled, and attuning is refused when the actor's
 * attunement slots are already full — the browser sheet warns after the fact,
 * but the phone should not let a player exceed the limit in the first place.
 */
export async function actorItemSetAttuned(user, actorId, itemId, attuned) {
  const actor = getOwnedActor(user, actorId);
  if (!itemId || typeof itemId !== "string") throw new Error("itemId is required");
  const item = actor.items.get(itemId);
  if (!item) throw new Error(`Item not found on actor: ${itemId}`);
  if (item.system?.attunement !== "required") {
    throw new Error("Item does not require attunement");
  }
  const next = attuned === undefined || attuned === null
    ? !item.system.attuned
    : Boolean(attuned);
  if (next && !item.system.attuned) {
    const att = actor.system?.attributes?.attunement;
    if (att && Number.isFinite(att.max) && (att.value ?? 0) >= att.max) {
      throw new Error("Attunement slots are full");
    }
  }
  await item.update({ "system.attuned": next });
  return { accepted: true, attuned: next };
}

/**
 * Prepare / unprepare a leveled spell (dnd5e 5.x: system.prepared, a number).
 * Only "prepared"-method leveled spells qualify — cantrips, innate, always and
 * pact-magic spells have no prepared state to flip. The per-class prepared
 * limit is advisory in dnd5e (the sheet lets you over-prepare), so it is
 * enforced only as a disabled toggle on the phone, not rejected here.
 */
export async function actorSpellSetPrepared(user, actorId, itemId, prepared) {
  const actor = getOwnedActor(user, actorId);
  if (!itemId || typeof itemId !== "string") throw new Error("itemId is required");
  const item = actor.items.get(itemId);
  if (!item) throw new Error(`Item not found on actor: ${itemId}`);
  if (item.type !== "spell") throw new Error("Not a spell");
  const sys = item.system ?? {};
  const method = sys.method ?? resolveSpellCastingMethod(sys);
  const preparable = method === "spell" && Number(sys.prepared) !== 2 && (sys.level ?? 0) > 0;
  if (!preparable) throw new Error("Spell cannot be prepared or unprepared");
  const cur = Number(sys.prepared) > 0;
  const next = prepared === undefined || prepared === null ? !cur : Boolean(prepared);
  await item.update({ "system.prepared": next ? 1 : 0 });
  return { accepted: true, prepared: next };
}

/**
 * Add or remove proficiency with an item (dnd5e: system.proficient — null means
 * "derive from the actor's proficiencies", 0/1 override it). Only weapons, tools
 * and armor carry the field. Writing an explicit 1/0 is exactly the manual
 * "I am / am not proficient with this" the player is asking for.
 */
export async function actorItemSetProficient(user, actorId, itemId, mode) {
  const actor = getOwnedActor(user, actorId);
  if (!itemId || typeof itemId !== "string") throw new Error("itemId is required");
  const item = actor.items.get(itemId);
  if (!item) throw new Error(`Item not found on actor: ${itemId}`);
  if (!("proficient" in (item.system ?? {}))) throw new Error("Item has no proficiency");
  // Mirrors the Foundry item-sheet dropdown: "auto" (null → derive from the
  // actor's proficiencies), "prof" (1 → proficient), "none" (0 → not proficient).
  let value;
  if (mode === "auto") value = null;
  else if (mode === "prof") value = 1;
  else if (mode === "none") value = 0;
  else throw new Error(`Unknown proficiency mode: ${mode}`);
  await item.update({ "system.proficient": value });
  return { accepted: true, mode };
}

/** "" (default) or a valid dnd5e ability key, lower-cased; throws on anything else. */
export function normalizeAbilityKey(a) {
  const key = String(a ?? "").toLowerCase();
  if (!key) return "";
  if (CONFIG.DND5E?.abilities?.[key]) return key;
  throw new Error(`Unknown ability: ${a}`);
}

export function abilityLabelFor(key) {
  if (!key) return "Default";
  const lbl = CONFIG.DND5E?.abilities?.[key]?.label;
  return lbl ? game.i18n.localize(lbl) : key.toUpperCase();
}

/**
 * Record a change that was applied immediately (no approval queue): a page in
 * the character's approval-log journal and a whispered chat line to the GMs.
 * Best-effort — a logging failure must not fail the change that already landed.
 */
export async function logDirectChange(actor, user, summary) {
  const line = `${String(user?.name ?? "Player")} · ${String(actor?.name ?? "character")}: ${summary}`;
  try {
    const journal = await ensureApprovalLog(actor);
    if (journal) {
      await journal.createEmbeddedDocuments("JournalEntryPage", [{
        name: summary,
        type: "text",
        text: { content: `<p>${escapeHtml(line)}</p>`, format: CONST.JOURNAL_ENTRY_PAGE_FORMATS.HTML }
      }]);
    }
  } catch (err) {
    console.warn(`[${MODULE_ID}] direct-change log failed`, err);
  }
  try {
    const gmIds = game.users.filter((u) => u.isGM).map((u) => u.id);
    if (gmIds.length && typeof ChatMessage?.create === "function") {
      await ChatMessage.create({
        content: `<p><strong>Bag of Worlds</strong></p><p>${escapeHtml(line)}</p>`,
        whisper: gmIds,
        speaker: { alias: "Bag of Worlds" }
      });
    }
  } catch (err) {
    console.warn(`[${MODULE_ID}] direct-change whisper failed`, err);
  }
}

/**
 * Ability used for a weapon's attack (dnd5e item.system.ability; "" = derive
 * from the weapon type). Applied immediately, logged, no approval.
 */
export async function actorItemSetAttackAbility(user, actorId, itemId, ability) {
  const actor = getOwnedActor(user, actorId);
  if (!itemId || typeof itemId !== "string") throw new Error("itemId is required");
  const item = actor.items.get(itemId);
  if (!item) throw new Error(`Item not found on actor: ${itemId}`);
  if (!("ability" in (item.system ?? {}))) throw new Error("Item has no attack ability");
  const key = normalizeAbilityKey(ability);
  await item.update({ "system.ability": key });
  await logDirectChange(actor, user, `Attack ability — ${item.name}: ${abilityLabelFor(key)}`);
  return { accepted: true, ability: key };
}

/** Ability used for initiative (dnd5e system.attributes.init.ability; "" = default). */
export async function actorSetInitiativeAbility(user, actorId, ability) {
  const actor = getOwnedActor(user, actorId);
  const key = normalizeAbilityKey(ability);
  await actor.update({ "system.attributes.init.ability": key });
  await logDirectChange(actor, user, `Initiative ability: ${abilityLabelFor(key)}`);
  return { accepted: true, ability: key };
}

/** Actor-wide spellcasting ability override (dnd5e system.attributes.spellcasting; "" = from class). */
export async function actorSetSpellcastingAbility(user, actorId, ability) {
  const actor = getOwnedActor(user, actorId);
  const key = normalizeAbilityKey(ability);
  await actor.update({ "system.attributes.spellcasting": key });
  await logDirectChange(actor, user, `Spellcasting ability: ${abilityLabelFor(key)}`);
  return { accepted: true, ability: key };
}

/**
 * Effective spellcasting ability: the actor override, else the first class's.
 * Uses `||` (not `??`): the class field is often an empty string rather than
 * null, which `??` would wrongly accept — so an empty value must fall through
 * to the derived getter.
 */
export function spellcastingAbilityEffective(actor) {
  const override = actor?.system?.attributes?.spellcasting;
  if (override) return override;
  for (const cls of Object.values(actor?.spellcastingClasses ?? {})) {
    const a = cls?.spellcasting?.ability || cls?.system?.spellcasting?.ability;
    if (a) return a;
  }
  return "";
}

/**
 * Spellcasting summary for the phone: the override, the effective ability, and
 * the save DC (8 + proficiency + ability mod) and spell attack bonus derived
 * from that effective ability. dc/attack are null for a non-caster.
 */
export function spellcastingInfo(actor) {
  const effective = spellcastingAbilityEffective(actor);
  const mod = Number(actor?.system?.abilities?.[effective]?.mod ?? 0);
  const prof = Number(actor?.system?.attributes?.prof ?? 0);
  const has = !!effective;
  return {
    ability: actor?.system?.attributes?.spellcasting ?? "",
    effective,
    dc: has ? 8 + prof + mod : null,
    attack: has ? prof + mod : null
  };
}

/**
 * Prepared-spell counts summed across the actor's spellcasting classes
 * (dnd5e computes value/max per class in system.spellcasting.preparation).
 * Returns null for non-preparing actors so the phone can hide the counter.
 */
export function spellcastingPreparation(actor) {
  let value = 0;
  let max = 0;
  let has = false;
  const classes = actor?.spellcastingClasses ?? {};
  for (const cls of Object.values(classes)) {
    const prep = cls?.system?.spellcasting?.preparation;
    if (prep && Number.isFinite(prep.max) && prep.max > 0) {
      has = true;
      value += Number(prep.value ?? 0);
      max += Number(prep.max ?? 0);
    }
  }
  return has ? { value, max } : null;
}

export async function actorCurrencyApplyOnActor(actor, key, quantityRaw) {
  const keyStr = String(key ?? "").trim();
  if (!keyStr) throw new Error("currency key is required");
  const qty = Number(quantityRaw);
  if (!Number.isFinite(qty)) throw new Error("quantity must be a finite number");
  const clamped = Math.min(CURRENCY_MAX, Math.max(0, Math.floor(qty)));
  const cur = foundry.utils.duplicate(actor.system?.currency ?? {});
  cur[keyStr] = clamped;
  await actor.update({ "system.currency": cur });
  return { accepted: true, key: keyStr, quantity: clamped };
}

export async function actorCurrencySet(user, actorId, key, quantity) {
  const actor = getOwnedActor(user, actorId);
  return actorCurrencyApplyOnActor(actor, key, quantity);
}

/** Set remaining spell slots (Trusted+). slotKey is spell1..spell9 or pact. */
export async function actorSpellSlotsSet(user, actorId, slotKey, valueRaw) {
  const actor = getOwnedActor(user, actorId);
  const key = String(slotKey ?? "").trim();
  if (!/^spell[1-9]$/.test(key) && key !== "pact") {
    throw new Error("slotKey must be spell1..spell9 or pact");
  }
  const slot = actor.system?.spells?.[key];
  if (!slot) throw new Error(`Spell slot not found: ${key}`);
  const max = Number(slot.override ?? slot.max ?? 0) || 0;
  const n = Number(valueRaw);
  if (!Number.isFinite(n)) throw new Error("value must be a finite number");
  const clamped = Math.min(max, Math.max(0, Math.floor(n)));
  // Same path Foundry's sheet uses (data-prop on the slot pips).
  await actor.update({ [`system.spells.${key}.value`]: clamped });
  return { accepted: true, slotKey: key, value: clamped, max };
}

/* ------------------------------------------------------------------ *
 * Revocable wrappers for the sheet edits players now make directly online.
 *
 * They capture the undo data, apply through the plain action, and log a
 * revocable entry — leaving the plain functions untouched for the many internal
 * callers (offline apply, creation, advancement) that must not be logged here.
 * ------------------------------------------------------------------ */

export async function actorItemCreateRevocable(user, actorId, uuid, nameHint = "") {
  const result = await actorItemCreate(user, actorId, uuid, nameHint);
  const actor = getOwnedActor(user, actorId);
  await recordRevocableChange(actor, user, `Added "${result?.name ?? nameHint}"`, {
    operation: "item.create",
    itemId: result?.itemId ?? null
  });
  return result;
}

export async function actorItemDeleteRevocable(user, actorId, itemId) {
  const actor = getOwnedActor(user, actorId);
  const item = actor.items.get(itemId);
  const itemData = item ? item.toObject() : null;
  const name = item?.name ?? "item";
  const result = await actorItemDelete(user, actorId, itemId);
  await recordRevocableChange(actor, user, `Removed "${name}"`, {
    operation: "item.delete",
    itemData
  });
  return result;
}

export async function actorItemSetQuantityRevocable(user, actorId, itemId, quantity) {
  const actor = getOwnedActor(user, actorId);
  const item = actor.items.get(itemId);
  const prior = item ? Number(item.system?.quantity) : null;
  const itemData = item ? item.toObject() : null;
  const name = item?.name ?? "item";
  const result = await actorItemSetQuantity(user, actorId, itemId, quantity);
  if (result?.deleted) {
    // Falling to zero becomes a delete; log it as one so revoke restores the item.
    await recordRevocableChange(actor, user, `Removed "${name}"`, {
      operation: "item.delete",
      itemData
    });
  } else {
    await recordRevocableChange(actor, user, `Set "${name}" quantity to ${result?.quantity}`, {
      operation: "item.quantity",
      itemId,
      prior,
      newValue: result?.quantity
    });
  }
  return result;
}

export async function actorCurrencySetRevocable(user, actorId, key, quantity) {
  const actor = getOwnedActor(user, actorId);
  const prior = Number(actor.system?.currency?.[String(key)] ?? 0) || 0;
  const result = await actorCurrencySet(user, actorId, key, quantity);
  await recordRevocableChange(actor, user, `Set ${key} to ${result?.quantity}`, {
    operation: "currency.set",
    key: String(key),
    prior,
    newValue: result?.quantity
  });
  return result;
}

export async function actorSpellSlotsSetRevocable(user, actorId, slotKey, valueRaw) {
  const actor = getOwnedActor(user, actorId);
  const key = String(slotKey ?? "").trim();
  const prior = Number(actor.system?.spells?.[key]?.value ?? 0) || 0;
  const result = await actorSpellSlotsSet(user, actorId, slotKey, valueRaw);
  await recordRevocableChange(actor, user, `Set ${result?.slotKey ?? key} slots to ${result?.value}`, {
    operation: "spellSlots.set",
    slotKey: result?.slotKey ?? key,
    prior,
    newValue: result?.value
  });
  return result;
}

/**
 * Set current / temporary hit points and the maximum-HP override (Trusted+).
 * Absolute values, clamped here so a malformed phone payload cannot push HP
 * past the actor's effective max or below zero. Every field is optional;
 * omitting one leaves it untouched.
 *
 * Max is dnd5e's manual override (`system.attributes.hp.max`, schema
 * `nullable: true, initial: null`, label DND5E.HitPointsOverride). Character
 * data prep only auto-calculates from hit-dice advancement + CON + bonuses
 * when the *source* value is exactly `null`, so `clearMax` writes null rather
 * than 0 — writing 0 would pin the maximum to zero, which is a valid but very
 * different thing.
 *
 * The resulting change reaches the phone through the normal `actor.hp` push
 * (registerActorHpPushHooks), so no extra emit is needed here.
 */
export async function actorHpSet(user, actorId, valueRaw, tempRaw, maxRaw, clearMax) {
  const actor = getOwnedActor(user, actorId);
  if (!actor.system?.attributes?.hp) throw new Error("Actor has no hit points");

  // Current and temporary HP are transient state any owner may set — the same
  // edit the desktop sheet offers them. The max override is a sheet mutation,
  // so it alone still needs Trusted. The action is no longer in
  // TRUSTED_REQUIRED_ACTIONS, which is why this is checked per field.
  const touchesMax = clearMax === true || (maxRaw !== undefined && maxRaw !== null);
  if (touchesMax && !isTrustedBridgeUser(user)) {
    throw new Error("Changing maximum HP requires Trusted Player role or higher");
  }

  // The max override changes what `value` may clamp to, so apply it first and
  // re-read the re-prepared derived data before touching value/temp.
  if (clearMax === true) {
    await actor.update({ "system.attributes.hp.max": null });
  } else if (maxRaw !== undefined && maxRaw !== null) {
    const m = Number(maxRaw);
    if (!Number.isFinite(m)) throw new Error("max must be a finite number");
    await actor.update({
      "system.attributes.hp.max": Math.min(HP_MAX_LIMIT, Math.max(0, Math.floor(m)))
    });
  }

  const hp = actor.system.attributes.hp;
  // effectiveMax includes tempmax; dnd5e clamps value to it in derived data.
  const effectiveMax = Math.max(0, Number(hp.effectiveMax ?? hp.max) || 0);
  const update = {};
  if (valueRaw !== undefined && valueRaw !== null) {
    const n = Number(valueRaw);
    if (!Number.isFinite(n)) throw new Error("value must be a finite number");
    update["system.attributes.hp.value"] = Math.min(effectiveMax, Math.max(0, Math.floor(n)));
  } else if (Number(actor._source?.system?.attributes?.hp?.value ?? 0) > effectiveMax) {
    // Lowering the max leaves the *stored* value above it — derived data hides
    // that but it would resurface if the max ever went back up. Pull it down.
    update["system.attributes.hp.value"] = effectiveMax;
  }
  if (tempRaw !== undefined && tempRaw !== null) {
    const t = Number(tempRaw);
    if (!Number.isFinite(t)) throw new Error("temp must be a finite number");
    update["system.attributes.hp.temp"] = Math.min(HP_TEMP_MAX, Math.max(0, Math.floor(t)));
  }
  if (Object.keys(update).length > 0) await actor.update(update);

  const after = actor.system.attributes.hp;
  return {
    accepted: true,
    value: Number(after.value) || 0,
    max: Number(after.max) || 0,
    temp: Number(after.temp) || 0,
    maxOverride: hpMaxOverrideOf(actor)
  };
}

/**
 * Apply damage or healing as a DELTA — the phone never computes the result.
 * Delegates to dnd5e's own `Actor5e#applyDamage`, the same entry point the
 * token HP bar uses (`modifyTokenAttribute` → `applyDamage(delta, {isDelta})`),
 * so temp-HP absorption, the `-hp.damage .. hp.value` clamp and the
 * dnd5e.preApplyDamage / dnd5e.applyDamage hooks all behave as in the browser.
 *
 * A bare number is passed deliberately: `applyDamage` sets `options.ignore = true`
 * for numeric input, i.e. resistances / immunities / vulnerabilities are NOT
 * re-applied. That matches the token-bar path and the usual table flow, where
 * the GM announces an already-reduced number. Typed application would need the
 * damage type from the roll, which the phone does not have.
 *
 * `kind`: "damage" (positive delta), "healing" (negative delta), or "temp"
 * (`applyTempHP`, which only raises temp HP — 5e temp HP does not stack).
 */
export async function actorHpApplyDelta(user, actorId, amountRaw, kindRaw) {
  const actor = getOwnedActor(user, actorId);
  if (!actor.system?.attributes?.hp) throw new Error("Actor has no hit points");
  const kind = String(kindRaw ?? "damage").trim().toLowerCase();
  if (!["damage", "healing", "temp"].includes(kind)) {
    throw new Error(`kind must be damage, healing or temp: ${kindRaw}`);
  }
  const n = Number(amountRaw);
  if (!Number.isFinite(n)) throw new Error("amount must be a finite number");
  // Direction comes from `kind`, so the magnitude is always positive here;
  // a negative "damage" would otherwise silently become healing.
  const amount = Math.min(HP_DELTA_MAX, Math.max(0, Math.floor(Math.abs(n))));
  if (amount === 0) throw new Error("amount must be greater than zero");

  const before = actor.system.attributes.hp;
  const priorValue = Number(before.value) || 0;
  const priorTemp = Number(before.temp) || 0;

  if (kind === "temp") {
    await actor.applyTempHP(amount);
  } else {
    await actor.applyDamage(kind === "healing" ? -amount : amount);
  }

  const after = actor.system.attributes.hp;
  return {
    accepted: true,
    kind,
    amount,
    value: Number(after.value) || 0,
    max: Number(after.max) || 0,
    temp: Number(after.temp) || 0,
    // How much the request actually moved things — temp absorption and the
    // max/zero clamps mean this often differs from `amount`.
    appliedToHp: (Number(after.value) || 0) - priorValue,
    appliedToTemp: (Number(after.temp) || 0) - priorTemp
  };
}


